        cmd = line.strip().lower()
        if cmd == "quit":
            break
        if cmd not in ("thrust", "left", "right", "shoot"):
            print("Unknown command: %s" % cmd)
            continue
        if cmd == "left":
            heading = (heading - 1) % 4
        elif cmd == "right":
            heading = (heading + 1) % 4
        elif cmd == "thrust":
            dx, dy = DIRS_V[heading]
            ship[0] = (ship[0] + dx * 2) % W
            ship[1] = (ship[1] + dy * 2) % H
        elif cmd == "shoot":
            dx, dy = DIRS_V[heading]
            for k in range(1, 4):
                target = ((ship[0] + dx * k) % W, (ship[1] + dy * k) % H)
                hit = None
                for rock in rocks:
                    if (rock[0], rock[1]) == target:
                        hit = rock
                        break
                if hit is not None:
                    rocks.remove(hit)
                    score += hit[4] * 20
                    if hit[4] == 2:
                        rocks.append([hit[0], hit[1], 1, 0, 1])
                        rocks.append([hit[0], hit[1], 0, 1, 1])
                    break
        for rock in rocks:
            rock[0] = (rock[0] + rock[2]) % W
            rock[1] = (rock[1] + rock[3]) % H
        if any((rock[0], rock[1]) == (ship[0], ship[1]) for rock in rocks):
            lives -= 1
            rocks = [r for r in rocks if (r[0], r[1]) != (ship[0], ship[1])]
        print("ship %s rocks %d score %d lives %d" % (tuple(ship), len(rocks), score, lives))
        if not rocks or lives <= 0:
            break
    print("FINAL SCORE: %d" % score)
    print("RESULT: %s" % ("WIN" if not rocks else "OUT OF LIVES" if lives <= 0 else "QUIT"))

if __name__ == "__main__":
    if "--play" in sys.argv:
        play()
    else:
        auto_play()
